import axios from 'axios';

const API_URL = 'https://localhost:7285/api';

const axiosInstance = axios.create({
    baseURL: API_URL,
    headers: {
        'Content-Type': 'application/json'
    },
    timeout: 10000,
    validateStatus: function (status) {
        return status >= 200 && status < 500;
    }
});

// Add auth token to requests
axiosInstance.interceptors.request.use(
    (config) => {
        const user = JSON.parse(localStorage.getItem('user') || '{}');
        if (user.token) {
            config.headers['Authorization'] = `Bearer ${user.token}`;
        }
        return config;
    },
    (error) => {
        return Promise.reject(error);
    }
);

export const getAllStocks = async () => {
    try {
        const response = await axiosInstance.get('/Store3/StockGetAll');
        return response.data;
    } catch (error) {
        console.error('Store3 - Stok verileri alınırken hata:', error);
        return { 
            success: false, 
            message: 'Stok verileri alınamadı', 
            store3Stocks: [] 
        };
    }
};

export const createStock = async (stockData) => {
    try {
        const data = {
            ...stockData,
            createdDate: new Date().toISOString()
        };
        const response = await axiosInstance.post('/Store3/StockCreate', data);
        return response.data;
    } catch (error) {
        console.error('Store3 - Stok oluşturulurken hata:', error);
        return { success: false, message: 'Stok oluşturulamadı' };
    }
};

export const updateStock = async (stockData) => {
    try {
        const response = await axiosInstance.put('/Store3/StockUpdate', stockData);
        return response.data;
    } catch (error) {
        console.error('Store3 - Stok güncellenirken hata:', error);
        return { success: false, message: 'Stok güncellenemedi' };
    }
};

export const deleteStock = async (id) => {
    try {
        const response = await axiosInstance.delete(`/Store3/StockDelete/${id}`);
        return response.data;
    } catch (error) {
        console.error('Store3 - Stok silinirken hata:', error);
        return { success: false, message: 'Stok silinemedi' };
    }
};

export const createSale = async (saleData) => {
    try {
        const response = await axiosInstance.post('/Store3/SaleCreate', saleData);
        return response.data;
    } catch (error) {
        console.error('Store3 - Satış oluşturulurken hata:', error);
        return { success: false, message: 'Satış oluşturulamadı' };
    }
};

export const createReturn = async (returnData) => {
    try {
        const response = await axiosInstance.post('/Store3/ReturnCreate', returnData);
        return response.data;
    } catch (error) {
        console.error('Store3 - İade oluşturulurken hata:', error);
        return { success: false, message: 'İade oluşturulamadı' };
    }
};

export const getAllSales = async () => {
    try {
        const response = await axiosInstance.get('/Store3/SaleGetAll');
        return response.data;
    } catch (error) {
        console.error('Store3 - Satış verileri alınırken hata:', error);
        return { success: false, message: 'Satış verileri alınamadı', error: error.message };
    }
};

export const getAllReturns = async () => {
    try {
        const response = await axiosInstance.get('/Store3/ReturnGetAll');
        return response.data;
    } catch (error) {
        console.error('Store3 - İade verileri alınırken hata:', error);
        return { success: false, message: 'İade verileri alınamadı', error: error.message };
    }
};
